{
  "items": [
    {
      "name": "one_le_pow_mul_abs_eval_div",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Field K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K] {f : Polynomial ℤ} {a b : ℤ},\n  0 < b →\n    Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f) ≠ 0 →\n      1 ≤ ↑b ^ f.natDegree * |Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f)|"
    },
    {
      "name": "RatFunc.denom_mul_dvd",
      "module_name": "Mathlib.FieldTheory.RatFunc.Basic",
      "kind": "theorem",
      "type": "∀ {K : Type u} [inst : Field K] (x y : RatFunc K), (x * y).denom ∣ x.denom * y.denom"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sup_sum",
      "module_name": "Mathlib.Algebra.MvPolynomial.SchwartzZippel",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R},\n  p ≠ 0 →\n    ∀ (S : Fin n → Finset R),\n      ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤\n        p.support.sup fun s => ∑ i, ↑(s i) / ↑(S i).card"
    },
    {
      "name": "Rat.mul_den_dvd",
      "module_name": "Mathlib.Data.Rat.Lemmas",
      "kind": "theorem",
      "type": "∀ (q₁ q₂ : ℚ), (q₁ * q₂).den ∣ q₁.den * q₂.den"
    },
    {
      "name": "MvPolynomial.eval₂",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "definition",
      "type": "{R : Type u} →\n  {S₁ : Type v} →\n    {σ : Type u_1} →\n      [inst : CommSemiring R] → [inst_1 : CommSemiring S₁] → (R →+* S₁) → (σ → S₁) → MvPolynomial σ R → S₁"
    },
    {
      "name": "RatFunc.eval_mul",
      "module_name": "Mathlib.FieldTheory.RatFunc.AsPolynomial",
      "kind": "theorem",
      "type": "∀ {K : Type u} [inst : Field K] {L : Type u} [inst_1 : Field L] (f : K →+* L) (a : L) {x y : RatFunc K},\n  Polynomial.eval₂ f a x.denom ≠ 0 →\n    Polynomial.eval₂ f a y.denom ≠ 0 → RatFunc.eval f a (x * y) = RatFunc.eval f a x * RatFunc.eval f a y"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_totalDegree",
      "module_name": "Mathlib.Algebra.MvPolynomial.SchwartzZippel",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R},\n  p ≠ 0 →\n    ∀ (S : Finset R),\n      ↑{f ∈ Fintype.piFinset fun x => S | (MvPolynomial.eval f) p = 0}.card / ↑S.card ^ n ≤ ↑p.totalDegree / ↑S.card"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sum_degreeOf",
      "module_name": "Mathlib.Algebra.MvPolynomial.SchwartzZippel",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R},\n  p ≠ 0 →\n    ∀ (S : Fin n → Finset R),\n      ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤\n        ∑ i, ↑(MvPolynomial.degreeOf i p) / ↑(S i).card"
    }
  ]
}
